import{_ as i,c as t,o as l,ag as e}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/usage.md","filePath":"zh-CN/guide/usage.md","lastUpdated":1794112334000}'),r={name:"zh-CN/guide/usage.md"};function o(d,a,n,h,s,c){return l(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><h2 id="基础导航" tabindex="-1">基础导航 <a class="header-anchor" href="#基础导航" aria-label="Permalink to &quot;基础导航&quot;">​</a></h2><h3 id="打开图片" tabindex="-1">打开图片 <a class="header-anchor" href="#打开图片" aria-label="Permalink to &quot;打开图片&quot;">​</a></h3><ul><li><strong>文件菜单</strong>：点击 文件 &gt; 打开，选择单张图片</li><li><strong>文件夹视图</strong>：点击 文件 &gt; 打开文件夹，浏览整个目录</li><li><strong>拖拽</strong>：把图片文件或文件夹直接拖到应用窗口中</li><li><strong>Chrome 扩展</strong>：在任意网站上点击扩展图标即可查看全部图片</li></ul><h2 id="finder-同步扩展" tabindex="-1">Finder 同步扩展 <a class="header-anchor" href="#finder-同步扩展" aria-label="Permalink to &quot;Finder 同步扩展&quot;">​</a></h2><h3 id="在-finder-中快速处理图片" tabindex="-1">在 Finder 中快速处理图片 <a class="header-anchor" href="#在-finder-中快速处理图片" aria-label="Permalink to &quot;在 Finder 中快速处理图片&quot;">​</a></h3><p>Finder 同步扩展会在 Finder 工具栏中添加一个 Nicasa 按钮，用于快速处理图片：</p><ol><li>在 Finder 中选中一张或多张图片</li><li>点击 Nicasa 工具栏按钮</li><li>选择 <strong>图片优化器</strong> 以压缩文件，或选择 <strong>AI 图像编辑器</strong> 以增强图片</li><li>Nicasa 会自动打开并处理选中的文件</li></ol><h3 id="支持的格式" tabindex="-1">支持的格式 <a class="header-anchor" href="#支持的格式" aria-label="Permalink to &quot;支持的格式&quot;">​</a></h3><p>该扩展支持：JPG、PNG、GIF、BMP、WebP、SVG、TIFF 和 ICO 文件。</p><h3 id="缩略图视图" tabindex="-1">缩略图视图 <a class="header-anchor" href="#缩略图视图" aria-label="Permalink to &quot;缩略图视图&quot;">​</a></h3><p>主界面以缩略图形式展示你的图片：</p><ul><li><strong>单击</strong>：选中一张图片</li><li><strong>双击</strong>：以完整视图打开</li><li><strong>右键</strong>：呼出带选项的上下文菜单</li></ul><h3 id="完整视图模式" tabindex="-1">完整视图模式 <a class="header-anchor" href="#完整视图模式" aria-label="Permalink to &quot;完整视图模式&quot;">​</a></h3><p>在全屏查看图片时：</p><ul><li><strong>缩放</strong>：使用鼠标滚轮或缩放控件</li><li><strong>平移</strong>：在放大后的图片上按住拖动</li><li><strong>切换</strong>：使用方向键或屏幕按钮切换到上一张/下一张</li></ul><h2 id="截图功能" tabindex="-1">截图功能 <a class="header-anchor" href="#截图功能" aria-label="Permalink to &quot;截图功能&quot;">​</a></h2><h3 id="截图" tabindex="-1">截图 <a class="header-anchor" href="#截图" aria-label="Permalink to &quot;截图&quot;">​</a></h3><ol><li>点击工具栏中的截图按钮，或使用键盘快捷键</li><li>选择你想要截取的区域</li><li>截图会自动在 Nicasa 中打开，方便立即编辑</li></ol><h3 id="屏幕录制权限" tabindex="-1">屏幕录制权限 <a class="header-anchor" href="#屏幕录制权限" aria-label="Permalink to &quot;屏幕录制权限&quot;">​</a></h3><p>截图功能需要屏幕录制权限：</p><ol><li>进入 系统设置 &gt; 隐私与安全性 &gt; 屏幕录制</li><li>勾选 Nicasa 旁边的复选框</li><li>如有必要，重启 Nicasa</li></ol><h2 id="ai-图像编辑器" tabindex="-1">AI 图像编辑器 <a class="header-anchor" href="#ai-图像编辑器" aria-label="Permalink to &quot;AI 图像编辑器&quot;">​</a></h2><h3 id="ai-编辑器概览" tabindex="-1">AI 编辑器概览 <a class="header-anchor" href="#ai-编辑器概览" aria-label="Permalink to &quot;AI 编辑器概览&quot;">​</a></h3><p>Nicasa 内置强大的 AI 图像增强工具：</p><ul><li><strong>自动增强</strong>：自动提升画质</li><li><strong>智能裁剪</strong>：智能给出裁剪建议</li><li><strong>色彩校正</strong>：由 AI 驱动的色彩调整</li><li><strong>降噪</strong>：去除噪点与颗粒</li><li><strong>锐化</strong>：智能锐化且不产生伪影</li></ul><h3 id="图像修复-inpainting-工具" tabindex="-1">图像修复（Inpainting）工具 <a class="header-anchor" href="#图像修复-inpainting-工具" aria-label="Permalink to &quot;图像修复（Inpainting）工具&quot;">​</a></h3><p>修复工具可以帮你：</p><ul><li>去除图片中不需要的物体</li><li>智能填补缺失部分</li><li>修复受损区域</li><li>清理背景</li></ul><h2 id="透明悬浮模式" tabindex="-1">透明悬浮模式 <a class="header-anchor" href="#透明悬浮模式" aria-label="Permalink to &quot;透明悬浮模式&quot;">​</a></h2><p>为设计师与画师量身打造：</p><ol><li>在 Nicasa 中打开一张图片</li><li>从「显示」菜单启用悬浮模式</li><li>使用滑块调节透明度</li><li>图片将始终浮于所有其他窗口之上</li><li>可用于描图、参考对照或 UI 比对</li></ol><h2 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to &quot;键盘快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>操作</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>打开文件</td></tr><tr><td><code>Cmd+Shift+O</code></td><td>打开文件夹</td></tr><tr><td><code>Space</code></td><td>下一张图片</td></tr><tr><td><code>Shift+Space</code></td><td>上一张图片</td></tr><tr><td><code>Cmd+F</code></td><td>切换全屏</td></tr><tr><td><code>Cmd+W</code></td><td>关闭窗口</td></tr><tr><td><code>Cmd+Q</code></td><td>退出应用</td></tr><tr><td><code>Delete</code></td><td>删除当前图片</td></tr><tr><td><code>Cmd+S</code></td><td>截图</td></tr><tr><td><code>Cmd+E</code></td><td>打开 AI 编辑器</td></tr><tr><td><code>Cmd+T</code></td><td>切换悬浮模式</td></tr></tbody></table><h2 id="chrome-扩展联动" tabindex="-1">Chrome 扩展联动 <a class="header-anchor" href="#chrome-扩展联动" aria-label="Permalink to &quot;Chrome 扩展联动&quot;">​</a></h2><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h3><ol><li>安装 <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Nicasa Chrome 扩展</a></li><li>扩展图标会出现在浏览器工具栏中</li></ol><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h3><ol><li>打开任意网站</li><li>点击 Nicasa 扩展图标</li><li>以网格形式查看该页面的所有图片</li><li>点击任意图片，即可在 Nicasa 中打开</li><li>对网页图片使用 Nicasa 的全部功能</li></ol><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h2><p>通过 Nicasa &gt; 偏好设置进入设置：</p><ul><li><strong>通用</strong>：默认文件夹、语言、主题</li><li><strong>浏览</strong>：缩略图尺寸、缩放行为、动画</li><li><strong>编辑器</strong>：AI 工具偏好、默认增强项</li><li><strong>扩展</strong>：Chrome 扩展设置</li><li><strong>隐私</strong>：数据收集偏好</li></ul><h2 id="支持的格式-1" tabindex="-1">支持的格式 <a class="header-anchor" href="#支持的格式-1" aria-label="Permalink to &quot;支持的格式&quot;">​</a></h2><p>Nicasa 支持所有常见图片格式：</p><ul><li><p><strong>标准格式</strong>：JPEG、PNG、GIF、BMP、TIFF、WebP</p></li><li><p><strong>RAW</strong>：CR2、NEF、ARW、DNG（需转换）</p></li><li><p><strong>矢量</strong>：SVG（需栅格化）</p></li><li><p><strong>动图</strong>：GIF、APNG</p></li><li><p>JPEG/JPG</p></li><li><p>PNG</p></li><li><p>GIF（静态）</p></li><li><p>BMP</p></li><li><p>TIFF</p></li><li><p>WebP</p></li><li><p>HEIC（在受支持的系统上）</p></li></ul><h2 id="技巧与提示" tabindex="-1">技巧与提示 <a class="header-anchor" href="#技巧与提示" aria-label="Permalink to &quot;技巧与提示&quot;">​</a></h2><ul><li>使用搜索栏按文件名快速查找图片</li><li>通过文件夹整理图片来创建图集</li><li>使用评分系统标记你喜欢的图片</li><li>通过「文件」菜单以不同格式导出图片</li></ul>',47)])])}const p=i(r,[["render",o]]);export{u as __pageData,p as default};
